]
for di,(panels,out) in enumerate(demos,1):
    print('demo',di)
    counts={c:0 for c in panels}
    bad=[]; occupancy=[]
    for r in range(4):
      for c in range(4):
        y=out[r][c]
        active=[color for color,rows in panels.items() if rows[r][c] != '0']
        counts[y]+=1
        if y not in active: bad.append((r,c,y,active))
        occupancy.append(len(active))
        print(f'({r},{c})={y}: active={"".join(active) or "-"}',end='; ')
      print()
    print('output counts',counts,'support violations',bad,'occupancy counts',{n:occupancy.count(n) for n in range(5)})

